12	/**
13	 * Assigns the {@code customerCode} formatted {@code <REGION>-<HASH8>}, the single region-and-hash owner
14	 * identity. REGION is the region code derived from the owner's {@link Owner#getPostcode() postcode} via
15	 * {@link Owner#regionOfPostcode(String)} (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or
16	 * {@code "UNKNOWN"} when the postcode is absent or in no known range. HASH8 is the first 8 upper-case
17	 * hex characters of the SHA-256 of the owner's {@link OwnerTelephone normalized (E.164) telephone}
18	 * concatenated with the last name.
19	 *
20	 * <p>The region-and-hash value would otherwise collide for two owners with the same normalized
21	 * telephone and last name in the same region. When the computed value matches an existing owner's
22	 * {@code customerCode}, it is de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2
23	 * or more that makes it unique. Every value built from the customer code — the
24	 * {@link AssignMembershipNumber membership number} and its {@link Owner#getCheckDigit() check digit},
25	 * the {@link AuditOwnerCreated create audit record} and the {@link Owner#getLocality() locality} — reads
26	 * this de-duplicated value.
27	 */
28	public class AssignCustomerCode {
29	
30	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
31	        String region = Owner.regionOfPostcode(owner.getPostcode());
32	        if (region == null) {
33	            region = "UNKNOWN";
34	        }
35	        String normalizedTelephone = OwnerTelephone.toE164(owner.getTelephone());
36	        if (normalizedTelephone == null) {
37	            normalizedTelephone = owner.getTelephone() == null ? "" : owner.getTelephone();
38	        }
39	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
40	        String base = region + "-" + hash8(normalizedTelephone + lastName);
41	
42	        Set<String> existingCodes = new HashSet<>();
43	        for (Owner existing : ownerRepository.findAll()) {
44	            if (existing.getCustomerCode() != null) {
45	                existingCodes.add(existing.getCustomerCode());
46	            }
47	        }
48	
49	        String customerCode = base;
50	        for (int n = 2; existingCodes.contains(customerCode); n++) {
51	            customerCode = base + "-" + n;
52	        }
53	        owner.setCustomerCode(customerCode);
54	    }
55	
56	    /** First 8 upper-case hex characters of the SHA-256 of {@code value}'s UTF-8 bytes. */
57	    private static String hash8(String value) {
58	        return Sha256.hex(value).substring(0, 8).toUpperCase(Locale.ROOT);
59	    }
